CREATE TABLE IF NOT EXISTS floorplan_items (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, item_object_type TEXT, tags TEXT, item_width INTEGER, item_height INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY (asset_id) REFERENCES assets(assetId) ON DELETE CASCADE);
